//! Actual private native readers + the original window-owned confirmation/cache.
//! Human choices and native owner metadata are fixtures, not Tauri acceptance.
use super::*;
use crate::pet_runtime::{native_system_admission_tests as fixture,admission_tests::Fixture,lease_controller::native_system_sound_task_tests::{Audio,serial},store::{Store,Fault,nonce},authority::Authority};
use std::{fs,sync::{atomic::{AtomicUsize,Ordering},Weak}};
fn clock()->u64{crate::assistant_memory::now()}
fn origin()->Origin{Origin{window:"system-fixture-window".into(),frame:crate::settings::review::Frame::fixture()}}
fn input(g:&Record,t:&ReviewTicket)->ConfirmInput{ConfirmInput{disclosure_consent:None,memory_consent:None,pet_id:g.spec.owner.pet_id.clone(),goal_id:g.id.clone(),revision:t.proposal.revision.clone(),token:t.token.clone(),approve:true}}
fn queued(r:ConfirmResult)->model::Receipt{if let ConfirmResult::Queued{receipt}=r{receipt}else{panic!("Expected exact native admission receipt")}}
fn prepare(f:&Fixture,a:&Audio,g:&Record,c:&crate::pet_config::Configuration,budget:Budget)->Review{
 let target=a.target(&f.path.join("system.json"),&g.spec.owner.pet_id,false);let file=f.path.join("system.json");let observe=Arc::new(move||serde_json::from_slice(&fs::read(&file).map_err(|_|Error::StorageUnavailable)?).map_err(|_|Error::InvalidInput));let now=clock();Review::prepare_system(g,fixture::evidence(g,c,now),budget,target,observe,&fixture::criteria(),"system-admission".into(),nonce().unwrap(),now).unwrap()
}
#[test]#[ignore="Private native services and actual Pending confirmation; no user audio/provider"]
fn system_control_confirmation_lost_ack_reuses_exact_original_system_authority_after_frame_replaced(){
 let _serial=serial();let audio=Audio::new();let f=Fixture::new();let g=fixture::draft(&f,&audio,"copilot");let c=fixture::config(&audio,&g);fixture::save(&f,&c);let original=origin();let review=fixture::review(&f,&audio,&g,&c);assert_eq!(path(&review.proposal()),ReviewPath::System);let mut cache=Reviews::default();let ticket=cache.insert(&original,review,nonce().unwrap(),clock()).unwrap();drop(cache.take_retired());let pending=cache.lookup(&original,&input(&g,&ticket),clock()).unwrap();let mut store=f.store();store.fault=Fault::AfterPublish;let observations=AtomicUsize::new(0);
 let receipt=queued(pending.confirm(&store,&f.path.join("authority"),true,|goal,now|{observations.fetch_add(1,Ordering::Relaxed);Ok(Ok((fixture::evidence(goal,&c,now),())))},clock).unwrap());assert_eq!(receipt.status,model::CommitStatus::Uncertain);let q=receipt.record;let row=&q.admissions[0];assert!(row.spec.system()&&row.spec.native_peer_plan.is_none()&&row.spec.resolved_model.is_empty());assert_eq!(row.spec.budget.max_model_calls,0);let file=f.path.join("authority").join(format!("{}.json",row.spec.decision_id));let before=fs::read(&file).unwrap();
 assert!(cache.retained_approved(&original,&q,ReviewPath::Deterministic,clock()).unwrap().is_none());let wrong=origin();assert!(cache.lookup(&wrong,&input(&g,&ticket),clock()).is_err());original.frame.invalidate_for_test();let replacement=origin();let alias=cache.retained_approved(&replacement,&q,ReviewPath::System,clock()).unwrap().unwrap();assert_eq!(alias.approval_scope,"confirmOriginalAdmission");assert_eq!(alias.proposal.native_system_plan,ticket.proposal.native_system_plan);assert_eq!(alias.proposal.budget,ticket.proposal.budget);let pending=cache.lookup(&replacement,&input(&g,&alias),clock()).unwrap();let receipt=queued(pending.confirm::<()>(&f.store(),&f.path.join("authority"),true,|_,_|panic!("ACK must not re-observe native target/provider or create authority"),||clock()+300_000).unwrap());assert_eq!(receipt.record.admissions.len(),1);assert_eq!(fs::read(&file).unwrap(),before);assert_eq!(observations.load(Ordering::Relaxed),1);assert!(Authority::existing(&f.path.join("authority")).unwrap().verify_queued(&q,clock()).is_ok());
 println!("SYSTEM_CONTROL_ACK ownSystemEvidence=true sourceBudgetTargetUnchanged=true frameReplacementExplicit=true noProviderReprobe=true noEffects=true");
}
#[test]#[ignore="Private native services and retained review revocation; no effects/provider"]
fn system_control_confirmation_rejects_revoked_grant_without_creating_authority_and_cannot_replay(){
 let _serial=serial();let audio=Audio::new();let f=Fixture::new();let g=fixture::draft(&f,&audio,"ollama");let c=fixture::config(&audio,&g);fixture::save(&f,&c);let origin=origin();let mut cache=Reviews::default();let ticket=cache.insert(&origin,fixture::review(&f,&audio,&g,&c),nonce().unwrap(),clock()).unwrap();drop(cache.take_retired());let pending=cache.lookup(&origin,&input(&g,&ticket),clock()).unwrap();let mut revoked=c.clone();revoked.pets.get_mut("ai_ollama").unwrap().system_access.as_mut().unwrap().revision="f".repeat(32);fixture::save(&f,&revoked);
 let result=pending.confirm(&f.store(),&f.path.join("authority"),true,|goal,now|Ok(Ok((fixture::evidence(goal,&revoked,now),()))),clock).unwrap();assert!(matches!(result,ConfirmResult::Blocked{retryable:false,..}));assert!(!f.path.join("authority").exists());assert!(f.store().read(&g.id,&g.spec.owner.pet_id).unwrap().admissions.is_empty());fixture::save(&f,&c);assert!(pending.confirm::<()>(&f.store(),&f.path.join("authority"),true,|_,_|panic!("Ended confirmation must not observe"),clock).is_err());
 println!("SYSTEM_CONTROL_REVOKE beforeAuthorityRejected=true restoredBytesCannotReplay=true noEffectsOrBudget=true");
}
#[test]#[ignore="Private native review anchors verify real deferred ownership; no effects/provider"]
fn system_control_cache_defers_duplicate_and_expired_native_reviews_until_after_global_mutex(){
 let _serial=serial();let audio=Audio::new();let f=Fixture::new();let g=fixture::draft(&f,&audio,"ollama");let c=fixture::config(&audio,&g);fixture::save(&f,&c);let origin=origin();let first=fixture::review(&f,&audio,&g,&c);let budget=first.proposal().budget.clone();let cache=Mutex::new(Reviews::default());let(token,weak)={let mut lock=cache.lock().unwrap();let t=lock.insert(&origin,first,nonce().unwrap(),clock()).unwrap();let weak=Arc::downgrade(lock.pending.get(&t.token).unwrap());(t,weak)};let retired=cache.lock().unwrap().take_retired();drop(retired);assert!(weak.upgrade().is_some());
 let duplicate=prepare(&f,&audio,&g,&c,budget);let retired={let mut lock=cache.lock().unwrap();let t=lock.insert(&origin,duplicate,nonce().unwrap(),clock()).unwrap();assert_eq!(t.token,token.token);assert_eq!(lock.pending.len(),1);assert_eq!(lock.retired.len(),1);lock.take_retired()};let duplicate_weak:Weak<Pending>=Arc::downgrade(&retired[0]);assert!(cache.try_lock().is_ok());drop(retired);assert!(duplicate_weak.upgrade().is_none());assert!(weak.upgrade().is_some());
 let retired={let mut lock=cache.lock().unwrap();lock.sweep(token.proposal.expires_at+1);assert!(lock.pending.is_empty());assert!(weak.upgrade().is_some(),"Native reader remains owned while global mutex is held");lock.take_retired()};assert!(cache.try_lock().is_ok());drop(retired);assert!(weak.upgrade().is_none());assert!(!f.path.join("authority").exists());
 println!("SYSTEM_CONTROL_CACHE duplicateAndExpiryDeferred=true nativeReadersDroppedOutsideGlobalMutex=true noAuthorityOrEffects=true");
}
